import { Accordion, Text } from "@chakra-ui/react";
import type { ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface UserSilenceTimeoutEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const UserSilenceTimeoutEventInfo = ({
  event,
  onClose,
}: UserSilenceTimeoutEventInfoProps) => (
  <DetailView title="User silence timeout" onClose={onClose}>
    <InfoField label="Timeout">
      <Text textStyle="sm">
        {event.timeout === undefined ? "Unavailable" : `${event.timeout} seconds`}
      </Text>
    </InfoField>
    <Accordion.Root collapsible multiple>
      <EventAccordionItem title="Event details" value="event-details">
        <CommonEventInfo event={event} />
      </EventAccordionItem>
    </Accordion.Root>
  </DetailView>
);
